}

/** The `n`-th `.btn` (or `.pick`) inside a panel, re-queried after a render. */
function child(el: FakeEl, className: string, n: number): FakeEl {
  const found = el.find(className)[n];
  if (!found) throw new Error(`no .${className} ${String(n)}`);
  return found;
}

