  it('a successful battle forwards removeCompanions then pvpResult with the replay to the game', async () => {
    const { doc, fake } = mounted(saveWith(COMPANIONS), {
      pvp: { ok: true, value: REPLAY_WON },
      thefts: { ok: true, value: { thefts: [] } },
